<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Audit Trail</title><link rel="stylesheet" href="/assets/css/legacy-style.css"><link rel="stylesheet" href="/assets/css/app.css"></head><body><main class="card card-wide"><h1>Audit Trail</h1><div style="margin-bottom:12px;display:flex;gap:8px;"><a href="/audit-trail/export/csv" class="btn btn-success btn-sm">&#11015; Export CSV</a><a href="/audit-trail/export/pdf" class="btn btn-info btn-sm" target="_blank">&#11015; Export PDF</a></div><p>Company: <?= htmlspecialchars($company['company_name'] ?? 'Unknown', ENT_QUOTES, 'UTF-8') ?></p><table class="table"><thead><tr><th>ID</th><th>User</th><th>Action</th><th>Entity</th><th>Entity ID</th><th>Details</th><th>Date</th></tr></thead><tbody><?php if (($rows ?? []) === []): ?><tr><td colspan="7">No audit events yet.</td></tr><?php else: foreach ($rows as $row): ?><tr><td><?= (int) $row['audit_id'] ?></td><td><?= htmlspecialchars((string) ($row['user_id'] ?? ''), ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($row['action_key'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($row['entity_type'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars((string) ($row['entity_id'] ?? ''), ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars((string) ($row['details'] ?? ''), ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($row['created_at'], ENT_QUOTES, 'UTF-8') ?></td></tr><?php endforeach; endif; ?></tbody></table><p><a href="/dashboard">Back to Dashboard</a></p></main></body></html>
